"use strict";(self["webpackChunkJorgeMopanc"]=self["webpackChunkJorgeMopanc"]||[]).push([[976],{5976:function(e){e.exports=JSON.parse('{"projects":[{"id":"qore-rewrite","category":"professional","isPublic":false,"featured":true,"caseStudySlug":"pos-sync-fiscal-compliance","projectType":"Enterprise Software - Business Management Platform","status":"In Production","title":"QORE - Enterprise Management Platform","description":"Complete enterprise system for centralized multi-store business management, developed with advanced technology stack: Node.js, Express.js, TypeScript, TypeORM and SQL Server on backend, React with TypeScript on frontend, and Socket.IO for real-time communication. Includes store management, sales analysis with statistical dashboards, inventory control, user management with granular permissions, and process automation. Key features: remote device configuration via proprietary ETPROXY protocol, business data synchronization, comparative analysis, product rankings, PDF/CSV export, intelligent price management, automatic backups and device-controlled licensing.","images":[{"src":"qore/Grafics.jpg","alt":"Interactive chart with sales statistics and business metrics","title":"Sales Statistics"},{"src":"qore/Chart.jpg","alt":"Dashboard with comparative performance charts and sales evolution","title":"Performance Charts"},{"src":"qore/Database.jpg","alt":"Database visualization with structured listing of articles and transactions","title":"Database View"},{"src":"qore/Receive.jpg","alt":"Article reception screen with inventory control and warehouse entries","title":"Stock Reception"},{"src":"qore/report.jpg","alt":"Detailed report with user listing and assigned permissions","title":"User Reports"},{"src":"qore/Stores.jpg","alt":"Store management interface with section, group and device configuration","title":"Store Management"},{"src":"qore/Tasks.jpg","alt":"System automatic task list with states and priorities","title":"Task Management"},{"src":"qore/VAT.jpg","alt":"VAT profile configuration with tax rules applied to articles and services","title":"VAT Configuration"},{"src":"qore/VAT1.jpg","alt":"VAT rate table with percentages and applicable categories","title":"VAT Table"}],"technologies":[{"name":"Node.js","icon":"nodejs-icon.svg"},{"name":"Express.js","icon":"express-js.svg"},{"name":"TypeScript","icon":"typescriptlang-icon.svg"},{"name":"TypeORM","icon":"Typeorm--Streamline-Simple-Icons.svg"},{"name":"SQL Server","icon":"microsoft-sql-server.svg"},{"name":"Socket.IO","icon":"socketio.svg"},{"name":"React","icon":"reactjs-icon.svg"},{"name":"CSS3","icon":"w3_css-icon.svg"},{"name":"RESTful API","icon":"getpostman-icon.svg"},{"name":"C#","icon":"visualstudio_code-icon.svg"},{"name":"InnoSetup","icon":"innosetup.svg"}],"links":{"repository":null,"website":null}},{"id":"alice4cash-payment-machine","category":"professional","isPublic":false,"featured":true,"projectType":"Embedded Systems - Payment Machine Backend","status":"In Production","title":"Alice4Cash - Automated Payment System","description":"Backend webservice for Alice4Cash automated payment machine, developed in pure C for controlling complex hardware including hoppers, coin/bill validators, recycler and security safe. Uses specialized CCTalk and EID003 protocols for peripheral communication, and MQTT for mobile app integration. Key challenges: rigorous memory management in restricted environment, memory leak prevention, binary data manipulation and real-time synchronization. Features: automatic value validation, change calculation, LED control, remote MQTT monitoring and detailed transaction logging.","images":[{"src":"alice4cash/homepage.jpg","alt":"Alice4Cash machine showing modern design with digital interface and money processing compartments","title":"Alice4Cash Machine"},{"src":"alice4cash/black.jpg","alt":"Internal components view including hoppers, validators, recycler and control system","title":"Hardware Components"},{"src":"alice4cash/white.jpg","alt":"Backend webservice development interface showing C code and MQTT configurations","title":"Backend Development"},{"src":"alice4cash/desc1.jpg","alt":"CCTalk and EID003 communication diagram between machine components","title":"Communication Protocols"},{"src":"alice4cash/desc2.jpg","alt":"Mobile application connected via MQTT for remote monitoring and machine control","title":"Mobile MQTT Integration"},{"src":"alice4cash/desc3.jpg","alt":"Testing environment with memory leak debugging and performance analysis","title":"Testing & Debugging"},{"src":"alice4cash/desc4.jpg","alt":"Testing environment with memory leak debugging and performance analysis","title":"Testing & Debugging"}],"technologies":[{"name":"C Programming","icon":"c-programming.svg"},{"name":"MQTT Protocol","icon":"mqtt-icon-solid.svg"},{"name":"CCTalk Protocol","icon":"binary-svgrepo-com.svg"},{"name":"EID003 Protocol","icon":"binary-svgrepo-com.svg"},{"name":"Embedded Systems","icon":"memory.svg"},{"name":"Linux Embedded","icon":"linux.svg"},{"name":"IoT Communication","icon":"iot.svg"}],"links":{"repository":null,"website":"https://www.alice4cash.com/"}},{"id":"q-scope-ai-trader","category":"personal","isPublic":true,"featured":true,"caseStudySlug":"qscope-quantum-elliott-wave-ai","projectType":"AI Algorithmic Trading System","status":"In Production","title":"Q-Scope AI Trading Platform","description":"Complete algorithmic trading platform with advanced artificial intelligence. Integrates NEURO-AI-CORE v4.0 with multi-timeframe analysis (15m, 1h, 4h), Elliott Wave Theory, advanced Fibonacci, and Quantum Engine. Full-stack system with TypeScript/Node.js backend, React/TypeScript frontend, dynamic risk management, continuous trade monitoring, and complete Binance API integration. Includes real-time dashboard, WebSocket for price streaming, JWT authentication, and licensing system.","images":[{"src":"q-scope-ai/login.jpg","alt":"User authentication and login interface","title":"Authentication System"},{"src":"q-scope-ai/dashboard.jpg","alt":"Main dashboard with real-time AI analysis","title":"AI Trading Dashboard"},{"src":"q-scope-ai/live_signals.jpg","alt":"Live AI signals with Elliott Wave and Fibonacci","title":"Live AI Signals"},{"src":"q-scope-ai/active_positions.jpg","alt":"Multi-timeframe analysis and quantum confluences","title":"Multi-Timeframe Analysis"},{"src":"q-scope-ai/how_ai_works.jpg","alt":"Dynamic risk management system","title":"Dynamic Risk Management"},{"src":"q-scope-ai/license.jpg","alt":"Licensing and access control system","title":"License Management"},{"src":"q-scope-ai/pair_setup.jpg","alt":"Trading pair configuration and setup","title":"Pair Configuration"},{"src":"q-scope-ai/training.jpg","alt":"AI model training and optimization","title":"AI Training Module"}],"technologies":[{"name":"Python","icon":"python-icon.svg"},{"name":"TypeScript","icon":"typescriptlang-icon.svg"},{"name":"Node.js","icon":"nodejs-icon.svg"},{"name":"React","icon":"reactjs-icon.svg"},{"name":"Express.js","icon":"express.svg"},{"name":"TypeORM","icon":"nodejs-icon.svg"},{"name":"MySQL","icon":"mysql-official.svg"},{"name":"Socket.IO","icon":"socketio.svg"},{"name":"Vite","icon":"js.svg"},{"name":"TailwindCSS","icon":"tailwindcss-icon.svg"},{"name":"Binance API","icon":"getpostman-icon.svg"},{"name":"JWT Authentication","icon":"getpostman-icon.svg"}],"links":{"repository":"https://github.com/mopanc/Q-scope-AI","website":null}},{"id":"smarttrade-ai","category":"personal","isPublic":true,"featured":true,"projectType":"AI Trading System","status":"In Development","title":"Smart Trade AI","description":"Advanced artificial intelligence system for cryptocurrency chart analysis that combines multiple machine learning technologies. Integrates Quantum based algorithms, Fibonacci, Elliott Waves, multi-timeframe analysis and portfolio optimization with Random Forest and Gradient Boosting models. Includes adaptive risk management that processes more than 50 technical indicators in real-time, replacing manual decisions with contextual analysis based on Elliott Wave patterns and AI confidence.","images":[{"src":"crypto_ai_analyser/dashboard.jpg","alt":"Real-time AI analysis dashboard","title":"AI Dashboard"},{"src":"crypto_ai_analyser/elliot_waves.jpg","alt":"ML models and Elliott Wave visualization","title":"ML Models"},{"src":"crypto_ai_analyser/fibonacci.jpg","alt":"Quantum Elliott Wave and Multi-Timeframe Analysis","title":"Quantum Analysis"},{"src":"crypto_ai_analyser/how_ai_works.jpg","alt":"Quantum Portfolio Optimizer and Risk Manager","title":"AI Risk Management"}],"technologies":[{"name":"Python","icon":"python-icon.svg"},{"name":"Scikit-learn","icon":"python-icon.svg"},{"name":"NumPy","icon":"python-icon.svg"},{"name":"Pandas","icon":"python-icon.svg"}],"links":{"repository":"https://github.com/mopanc/trading-bot","website":null}},{"id":"dataconvert-saas-platform","category":"personal","isPublic":true,"featured":true,"caseStudySlug":"dataconvert-template-processing","projectType":"SaaS Data Processing Platform","status":"In Development","title":"DataConvert - Professional Data Processing Platform","description":"Complete SaaS platform for corporate data processing automation. Multi-tenant system with custom template creation, intelligent PDF table extraction using dual AI (tabula-py + pdfplumber), visual column mapping, and automated PDF→CSV/JSON conversion. Full-stack architecture with Node.js/TypeScript/Express backend, React/TypeScript frontend, JWT authentication, plan system (Free/Personal/Enterprise), and Python FastAPI service for PDF processing. Includes analytics dashboard, template management, drag-&-drop upload, and multi-tenancy system for enterprises.","images":[{"src":"data-convert/Landing_page.jpg","alt":"Registration with plan selection and multi-tenancy","title":"User Registration"},{"src":"data-convert/dashboard.jpg","alt":"Main dashboard with statistics and recent templates","title":"Analytics Dashboard"},{"src":"data-convert/my_templates.jpg","alt":"Template management with filters and advanced search","title":"Template Management"},{"src":"data-convert/import.jpg","alt":"Upload interface with drag-and-drop and batch processing","title":"File Import System"},{"src":"data-convert/subscriptions.jpg","alt":"Authentication interface with JWT system","title":"Authentication System"}],"technologies":[{"name":"TypeScript","icon":"typescriptlang-icon.svg"},{"name":"React","icon":"reactjs-icon.svg"},{"name":"Node.js","icon":"nodejs-icon.svg"},{"name":"Express.js","icon":"express.svg"},{"name":"TypeORM","icon":"nodejs-icon.svg"},{"name":"PostgreSQL","icon":"mysql-official.svg"},{"name":"Python","icon":"python-icon.svg"},{"name":"FastAPI","icon":"python-icon.svg"},{"name":"Vite","icon":"js.svg"},{"name":"TailwindCSS","icon":"tailwindcss-icon.svg"},{"name":"Tabula-py","icon":"python-icon.svg"},{"name":"PDFplumber","icon":"python-icon.svg"},{"name":"Pandas","icon":"python-icon.svg"},{"name":"JWT Authentication","icon":"getpostman-icon.svg"},{"name":"Bcrypt","icon":"visualstudio_code-icon.svg"},{"name":"Axios","icon":"js.svg"},{"name":"Multer","icon":"nodejs-icon.svg"}],"links":{"repository":"https://github.com/mopanc/dataconvert-platform","website":null}},{"id":"google-glass-website","category":"personal","isPublic":true,"featured":false,"projectType":"Responsive Website with Modern Redesign","status":"Completed","title":"Google Glass - Modernized Website","description":"Complete redesign of my first web project - a Google Glass website originally created following Gustavo Guanabara\'s course. Transformed the classic design into a modern and professional experience while maintaining all original structure and content. Implemented premium design system with sophisticated earthy palette, advanced navigation menu, complete responsiveness, fluid animations, and micro-interactions. Project includes modernized form with validation, interactive image gallery, optimized video playback, and hierarchical typography. A tribute to initial learning, elevated to current frontend development standards.","images":[{"src":"google_glass/homepage.jpg","alt":"Homepage with glassmorphism header and premium design","title":"Homepage Premium Design"},{"src":"google_glass/fotos.jpg","alt":"Modern navigation menu with sophisticated hover effects","title":"Advanced Navigation"},{"src":"google_glass/multimidia.jpg","alt":"Responsive layout with modern grid and premium typography","title":"Modern Content Layout"},{"src":"google_glass/specs.jpg","alt":"Modernized contact form with real-time validation","title":"Modern Contact Form"}],"technologies":[{"name":"HTML5","icon":"w3_html5-icon.svg"},{"name":"CSS3","icon":"w3_css-icon.svg"},{"name":"JavaScript ES6+","icon":"js.svg"},{"name":"Media Queries","icon":"w3_css-icon.svg"},{"name":"Google Fonts","icon":"google_analytics-icon.svg"},{"name":"Accessibility (A11y)","icon":"w3_html5-icon.svg"},{"name":"Cross-browser Support","icon":"visualstudio_code-icon.svg"}],"links":{"repository":"https://github.com/mopanc/projeto-glass-html5","website":null}},{"id":"digital-garage-management","category":"personal","isPublic":true,"featured":false,"projectType":"Web Application - Garage Management System","status":"Completed","title":"Digital Garage Management System","description":"Modern and professional garage management system built with React.js and Ant Design. The application provides complete management of automotive services with online booking, customer management, and administrative controls. Features a stunning homepage with Ferrari theme, professional workshop color scheme (dark blues and oranges), and cutting-edge technology showcase. The system includes three main sections: a marketing homepage with hero banner and service features, a comprehensive booking management system with CRUD operations, and an administrative panel for service types and booking oversight. Built with modern React patterns, the application features responsive design, animated components with fade-in effects, professional table layouts with tags and status indicators, modal forms for creating and editing bookings, and a clean administrative interface with tabbed navigation. The backend is powered by JSON Server providing RESTful API endpoints for services management. Implements modern CSS with gradients, glassmorphism effects, hover animations, and mobile-responsive design. The interface includes professional headers with navigation, modern card layouts, advanced form handling with validation, and a sophisticated color scheme reflecting automotive workshop aesthetics.","images":[{"src":"garage/banner.jpg","alt":"Homepage showing Digital Garage hero banner with Ferrari theme and service features","title":"Digital Garage Homepage"},{"src":"garage/features.jpg","alt":"Booking management interface with table, filters and CRUD operations","title":"Booking Management System"},{"src":"garage/tipos.jpg","alt":"Administrative panel for service type management","title":"Administrative Panel"},{"src":"garage/admin1.jpg","alt":"Booking form interface with validation and controls","title":"Booking Forms Interface"},{"src":"garage/admin2.jpg","alt":"Advanced booking management with status tracking","title":"Advanced Booking Management"}],"technologies":[{"name":"React.js","icon":"reactjs-icon.svg"},{"name":"Ant Design","icon":"reactjs-icon.svg"},{"name":"JavaScript ES6+","icon":"js.svg"},{"name":"CSS3","icon":"w3_css-icon.svg"},{"name":"JSON Server","icon":"js.svg"},{"name":"Axios","icon":"js.svg"},{"name":"React Router","icon":"reactjs-icon.svg"}],"links":{"repository":"https://github.com/mopanc/digital-garage-management","website":null}},{"id":"capitalges-website","category":"professional","isPublic":false,"featured":true,"projectType":"Web Development - Corporate Website","status":"In Production","title":"CapitalGes - Business Consulting","description":"Professional corporate website developed for CapitalGes, a Portuguese company specializing in business consulting for micro, small, and medium enterprises. The project presents a complete web solution focused on accounting, taxation, management support, and human resources. Developed with pure PHP and robust architecture using Nginx as web server, the site offers a modern and intuitive user experience with minimalist and professional design. Key features include detailed presentation of business services, newsletter system for exclusive content, news and updates area, social media integration (LinkedIn), direct contact forms, and dynamic content management. The project was built with focus on performance and SEO, implementing Google Analytics for traffic analysis, Google Tag Manager for script management, search engine optimization, fully responsive design, and compliance with cookie regulations. The interface uses a neutral and professional color palette (white, gray, black) with clear and legible typography, custom minimalist icons, smooth animations in JavaScript and jQuery, and structured content organization by sections. Technical development employs pure PHP for greater control and performance, Nginx for serving static and dynamic content, SASS for advanced and maintainable styling, JavaScript and jQuery for interactivity, semantic HTML5 for accessibility, and CSS3 with Grid and Flexbox for responsive layouts. This project represents a complete business solution that combines professional design with robust functionality, providing CapitalGes with a solid and reliable digital presence to attract and serve their clients in the business consulting sector.","images":[{"src":"capitalges/homepage.jpg","alt":"CapitalGes homepage showing business consulting services with minimalist design","title":"Main Page"},{"src":"capitalges/news.jpg","alt":"Services page detailing accounting, taxation and management support","title":"Business Services"},{"src":"capitalges/aboutus.jpg","alt":"About page with company mission and values of CapitalGes","title":"About the Company"},{"src":"capitalges/contacts.jpg","alt":"Contact page with form and location information","title":"Contacts and Location"},{"src":"capitalges/mobile1.jpg","alt":"News and updates area about business consulting","title":"News Center"},{"src":"capitalges/mobile2.jpg","alt":"News and updates area about business consulting","title":"News Center"}],"technologies":[{"name":"PHP","icon":"php-icon.svg"},{"name":"Nginx","icon":"docker-icon.svg"},{"name":"JavaScript","icon":"js.svg"},{"name":"jQuery","icon":"jquery-vertical.svg"},{"name":"HTML5","icon":"w3_html5-icon.svg"},{"name":"CSS3","icon":"w3_css-icon.svg"},{"name":"Sass","icon":"sass-lang-icon.svg"},{"name":"Google Analytics","icon":"google_analytics-icon.svg"},{"name":"Responsive Design","icon":"w3_css-icon.svg"}],"links":{"repository":null,"website":"https://www.capitalges.pt"}},{"id":"amf-shoes-website","category":"professional","isPublic":false,"featured":true,"projectType":"Web Development - Corporate E-commerce Website","status":"In Production","title":"AMF Safety Shoes - Corporate Website","description":"Corporate website developed for AMF Safety Shoes, Portuguese leader in technical safety footwear (650,000 pairs/year, €20M revenue). Premium multilingual digital platform (PT/EN) that combines corporate storytelling with e-commerce functionalities. Developed with PHP, Nginx and focus on sustainability, R&D innovation and quality certifications.","images":[{"src":"amf/homepage.jpg","alt":"AMF Safety Shoes homepage with hero section and presentation of the leading safety footwear company","title":"Corporate Homepage"},{"src":"amf/page1.jpg","alt":"AMF internal page showing detailed content about products and services","title":"Content Page"},{"src":"amf/page2.jpg","alt":"Second internal page with company information and processes","title":"Company Information"},{"src":"amf/mobile1.jpg","alt":"AMF mobile site version showing responsive design and optimized navigation","title":"Mobile Interface 1"},{"src":"amf/mobile2.jpg","alt":"Second mobile interface demonstrating design adaptability for mobile devices","title":"Mobile Interface 2"}],"technologies":[{"name":"PHP","icon":"php-icon.svg"},{"name":"Nginx","icon":"docker-icon.svg"},{"name":"JavaScript","icon":"js.svg"},{"name":"jQuery","icon":"jquery-vertical.svg"},{"name":"HTML5","icon":"w3_html5-icon.svg"},{"name":"CSS3","icon":"w3_css-icon.svg"},{"name":"Sass","icon":"sass-lang-icon.svg"},{"name":"Google Analytics","icon":"google_analytics-icon.svg"},{"name":"Google Tag Manager","icon":"google_analytics-icon.svg"},{"name":"Responsive Design","icon":"w3_css-icon.svg"},{"name":"Multilingual Support","icon":"w3_html5-icon.svg"}],"links":{"repository":null,"website":"https://www.amfshoes.com/pt/"}},{"id":"toworkfor-ecommerce","category":"professional","isPublic":false,"featured":true,"projectType":"E-commerce Development - B2C Online Store","status":"In Production","title":"Toworkfor - Safety Footwear E-commerce","description":"Complete B2C e-commerce platform developed for Toworkfor, specialized in professional safety footwear. The project presents a modern and functional online store with extensive catalog of workplace safety products, user management system, and optimized shopping experience. Developed with pure PHP and robust architecture, the site offers advanced e-commerce functionalities including intelligent shopping cart, secure checkout system, real-time inventory management, multiple payment methods, and order tracking system. The platform features premium responsive design, multilingual support (Portuguese, English, Spanish, French, German), advanced filtering system by category, size, brand and price, intelligent product search, review and rating system, loyalty program, and social media integration. Technical development includes robust PHP backend, JavaScript and jQuery for interactivity, semantic HTML5 for optimized SEO, responsive CSS3 with mobile-first design, Google Analytics and Tag Manager integration, Facebook Pixel for remarketing, GDPR compliant cookie management system, and performance optimization. The interface highlights intuitive category navigation, product visualization with zoom, wishlist system, product comparator, shipping calculator, integrated support chat, and personalized customer area. This project represents a complete e-commerce solution that combines business functionality with superior user experience, positioning Toworkfor as digital leader in the personal protective equipment and professional safety footwear market.","images":[{"src":"toworkfor/homepage.jpg","alt":"Toworkfor homepage showing safety footwear catalog with modern design and intuitive navigation","title":"E-commerce Homepage"},{"src":"toworkfor/products.jpg","alt":"Product page with advanced filters, responsive grid and detailed safety footwear information","title":"Product Catalog"},{"src":"toworkfor/shoes.jpg","alt":"Product details page showing technical specifications, images and purchase options","title":"Product Details"},{"src":"toworkfor/login.jpg","alt":"Login and registration interface with modern design and form validation","title":"Authentication System"},{"src":"toworkfor/menu.jpg","alt":"Navigation menu with organized categories and advanced search system","title":"Navigation and Menu"},{"src":"toworkfor/mobile1.jpg","alt":"Optimized mobile interface showing responsiveness and mobile device adaptation","title":"Mobile Interface 1"},{"src":"toworkfor/mobile2.jpg","alt":"Second mobile screen demonstrating shopping cart and mobile checkout process","title":"Mobile Interface 2"}],"technologies":[{"name":"PHP","icon":"php-icon.svg"},{"name":"MySQL","icon":"mysql-official.svg"},{"name":"JavaScript","icon":"js.svg"},{"name":"jQuery","icon":"jquery-vertical.svg"},{"name":"HTML5","icon":"w3_html5-icon.svg"},{"name":"CSS3","icon":"w3_css-icon.svg"},{"name":"Bootstrap","icon":"getbootstrap-icon.svg"},{"name":"Google Analytics","icon":"google_analytics-icon.svg"},{"name":"Google Tag Manager","icon":"google_analytics-icon.svg"},{"name":"Facebook Pixel","icon":"slack-icon.svg"},{"name":"Responsive Design","icon":"w3_css-icon.svg"},{"name":"Multilingual Support","icon":"w3_html5-icon.svg"},{"name":"Payment Integration","icon":"getpostman-icon.svg"},{"name":"GDPR Compliance","icon":"visualstudio_code-icon.svg"}],"links":{"repository":null,"website":"https://www.toworkfor.pt/pt/"}},{"id":"loucas-falcao-ecommerce","category":"professional","isPublic":false,"featured":true,"projectType":"E-commerce Development - B2B/B2C Wholesale Platform","status":"In Production","title":"Louças Falcão - Porcelain and Decoration E-commerce","description":"Sophisticated e-commerce platform developed for Louças Falcão, Portuguese company specialized in porcelain, ceramics and decorative items based in Barcelos. The project presents a complete digital solution that combines B2B and B2C sales, offering an extensive catalog of decoration products, household utilities and collectible items. Developed with modern web technologies, the site serves both professional clients and end consumers, with functionalities adapted for both segments. The platform offers advanced navigation through multiple categories including porcelain/ceramics, marfinites/resins, glass, artificial flowers/plants, wicker/wood, porcelain dolls, toys/plushes, textiles/footwear and thematic decorations. The e-commerce system includes advanced search engine with specific filters, distinction between national and imported products, separation between decorative and utility items, professional login system for B2B clients, complete multilingual support (Portuguese, English, French, Spanish), and integration with payment and logistics systems. Technical development employs robust architecture for complex inventory management, differentiated B2B/B2C pricing system, SEO optimization for multiple languages, responsive design for all devices, Google Analytics integration for detailed analysis, and administrative interface for product and order management. The user experience highlights intuitive navigation through extensive categories, professional product visualization with zoom, wishlist and comparison system, quantity calculator for professional orders, and personalized customer area with purchase history. This project represents a specialized e-commerce solution that positions Louças Falcão as digital reference in the Portuguese decoration and household utilities market, combining artisanal tradition with modern technology.","images":[{"src":"falcao/homepage.jpg","alt":"Louças Falcão homepage showing porcelain, ceramics and decorative items catalog with professional navigation","title":"E-commerce Homepage"},{"src":"falcao/products.jpg","alt":"Product page with organized grid, advanced filters and detailed categorization of pottery and decoration","title":"Product Catalog"},{"src":"falcao/toys.jpg","alt":"Toys and collectibles section showing catalog diversity and category organization","title":"Toys and Collectibles Category"}],"technologies":[{"name":"PHP","icon":"php-icon.svg"},{"name":"MySQL","icon":"mysql-official.svg"},{"name":"JavaScript","icon":"js.svg"},{"name":"jQuery","icon":"jquery-vertical.svg"},{"name":"HTML5","icon":"w3_html5-icon.svg"},{"name":"CSS3","icon":"w3_css-icon.svg"},{"name":"Bootstrap","icon":"getbootstrap-icon.svg"},{"name":"Google Analytics","icon":"google_analytics-icon.svg"},{"name":"Responsive Design","icon":"w3_css-icon.svg"},{"name":"Multilingual Support","icon":"w3_html5-icon.svg"},{"name":"Advanced Search","icon":"google_analytics-icon.svg"},{"name":"B2B Integration","icon":"business.svg"},{"name":"Inventory Management","icon":"inventory.svg"},{"name":"SEO Optimization","icon":"google_analytics-icon.svg"}],"links":{"repository":null,"website":"https://www.loucasfalcao.com/pt/porcelana-ceramica"}},{"id":"frontend-training-collection","category":"personal","isPublic":true,"featured":false,"projectType":"Web Development - Frontend Training Collection","status":"Completed","title":"Frontend Training Collection - Clone Projects","description":"Collection of frontend training projects developed during my self-taught programming journey, showcasing dedication to mastering HTML5, CSS3, and vanilla JavaScript through real-world interface reproduction. This collection demonstrates my autodidactic approach to learning web development by recreating popular and recognizable interfaces from major platforms. Projects include pixel-perfect recreations of Facebook\'s login page with authentic styling and form layouts, Instagram\'s login interface featuring gradient backgrounds and modern UI elements, Netflix\'s main homepage with responsive grid layouts and hover effects, Game of Thrones official website with immersive dark theme and medieval aesthetics, and a custom-designed modern calculator with sleek interface and full functionality. Each project focuses on different aspects of frontend development: responsive design principles, CSS Grid and Flexbox layouts, modern CSS techniques including gradients and animations, JavaScript DOM manipulation and event handling, form validation and user interactions, and cross-browser compatibility. These projects represent my commitment to continuous learning and skill development, demonstrating progression from basic HTML/CSS to more complex JavaScript interactions. Built without frameworks to master fundamental web technologies, each clone project captures the essence and functionality of the original while serving as practical exercises in frontend development best practices.","images":[{"src":"frontend/insta.jpg","alt":"Instagram login interface recreation with gradient backgrounds","title":"Instagram Login Clone"},{"src":"frontend/facebook.jpg","alt":"Facebook login page clone with authentic blue theme and form layout","title":"Facebook Login Clone"},{"src":"frontend/netflix.jpg","alt":"Netflix main page clone with movie grid and responsive design","title":"Netflix Homepage Clone"},{"src":"frontend/gameofthrones.jpg","alt":"Game of Thrones website clone with dark medieval theme","title":"Game of Thrones Website Clone"},{"src":"frontend/calc.jpg","alt":"Custom modern calculator with sleek design and full functionality","title":"Modern Calculator (Original Design)"},{"src":"frontend/maccalc.jpg","alt":"Mac-style calculator with advanced functionality and design","title":"Mac Calculator Clone"}],"technologies":[{"name":"HTML5","icon":"w3_html5-icon.svg"},{"name":"CSS3","icon":"w3_css-icon.svg"},{"name":"JavaScript ES6+","icon":"js.svg"},{"name":"Responsive Design","icon":"w3_css-icon.svg"},{"name":"CSS Grid","icon":"grid.svg"},{"name":"Flexbox","icon":"flexbox.svg"}],"links":{"repository":"https://github.com/mopanc/frontend-training-clones","website":null}},{"id":"jobscalc-freelancer-calculator","category":"personal","isPublic":true,"featured":false,"projectType":"Web Application - Freelancer Project Calculator","status":"Completed","title":"JobsCalc - Freelancer Project Calculator","description":"Full-stack web application developed during Rocketseat\'s Maratona Discover bootcamp for calculating freelancer project estimates and managing work hours. Features comprehensive project management with CRUD operations, automatic budget calculations based on hourly rates, project status tracking (in progress/completed), and professional dashboard with real-time metrics. Includes user profile management with customizable hourly rates, vacation planning, and work schedule configuration. Built with modern Node.js architecture using Express, EJS templating, and SQLite database. The application provides an intuitive interface for freelancers to track their projects, calculate fair pricing, and manage their professional time effectively.","images":[{"src":"jobs_calc/dashboard.jpg","alt":"Professional dashboard showing project overview with status cards and metrics","title":"Project Dashboard"},{"src":"jobs_calc/profile.jpg","alt":"Profile management page with hourly rate calculator and work planning","title":"Profile & Rate Configuration"},{"src":"jobs_calc/create.jpg","alt":"Job creation form with automatic budget calculation","title":"New Project Creation"}],"technologies":[{"name":"Node.js","icon":"nodejs-icon.svg"},{"name":"Express.js","icon":"express.svg"},{"name":"EJS","icon":"ejs.svg"},{"name":"SQLite","icon":"sqlite.svg"},{"name":"JavaScript ES6+","icon":"js.svg"},{"name":"HTML5","icon":"w3_html5-icon.svg"},{"name":"CSS3","icon":"w3_css-icon.svg"},{"name":"MVC Architecture","icon":"architecture.svg"},{"name":"RESTful API","icon":"getpostman-icon.svg"},{"name":"Nodemon","icon":"nodemon.svg"},{"name":"NPM","icon":"npm.svg"}],"links":{"repository":"https://github.com/mopanc/MaratonaDiscover","website":null}},{"id":"marvel-digital-catalog","category":"personal","isPublic":true,"featured":false,"projectType":"Web Application - Marvel Comics & Characters Catalog","status":"Completed","title":"Marvel Digital Catalog","description":"Modern and interactive web application for exploring the Marvel universe, featuring comics and characters from the official Marvel API. Built with vanilla JavaScript and modern CSS techniques, the application provides a premium user experience with glassmorphism design, real-time search, advanced filtering, and a fully functional shopping cart system. Features include responsive grid layouts displaying comics and characters with detailed information, favorites system with localStorage persistence, modal dialogs for detailed views, and comprehensive cart management with checkout simulation. The interface includes a sleek navbar with cart counter, search functionality with debounce, category filters (All, Recent, Popular, Favorites), and smooth animations throughout. Implements modern CSS Grid for responsive layouts, backdrop-filter effects for glassmorphism design, and gradient animations for visual appeal. The application consumes the Marvel API with proper authentication, handles API errors gracefully, and provides loading states for better UX. Built with modular JavaScript architecture, component-based structure, and mobile-first responsive design.","images":[{"src":"marvel/home.jpg","alt":"Homepage showing Marvel comics grid with search bar and filters","title":"Comics Catalog Homepage"},{"src":"marvel/characteres.jpg","alt":"Characters page displaying Marvel heroes and villains with stats","title":"Marvel Characters Gallery"},{"src":"marvel/cart.jpg","alt":"Shopping cart interface with item management and checkout","title":"Shopping Cart System"},{"src":"marvel/detail.jpg","alt":"Detail interface with detailed information","title":"Detailed Modal"}],"technologies":[{"name":"JavaScript ES6+","icon":"js.svg"},{"name":"HTML5","icon":"w3_html5-icon.svg"},{"name":"CSS3","icon":"w3_css-icon.svg"},{"name":"Marvel API","icon":"getpostman-icon.svg"},{"name":"Bootstrap 4","icon":"getbootstrap-icon.svg"},{"name":"jQuery","icon":"jquery-vertical.svg"}],"links":{"repository":"https://github.com/mopanc/catalogo-digital-marvel","website":null}},{"id":"monty-hall-problem","category":"personal","isPublic":true,"featured":false,"projectType":"Web Development - Interactive Educational Game","status":"Completed","title":"Monty Hall Problem - Interactive Game","description":"Interactive educational web application that demonstrates the famous Monty Hall probability paradox through an engaging game interface. This project recreates the classic game show scenario where players choose between three doors, with only one containing a prize, to illustrate the counterintuitive probability concept that switching doors increases winning chances from 33.3% to 66.7%. Built with Vue.js 2, the application features a visually appealing interface with realistic 3D-styled doors, animated gift presentations, and comprehensive educational content explaining the mathematical principle behind the paradox. The game includes step-by-step instructions, probability visualization cards, and a clean three-column layout that fits entirely on one screen for optimal user experience. Key features include interactive door selection and opening mechanics, animated gift reveal with bouncing effects and sparkles, automatic game state management with door reset functionality, responsive design that works across all devices, educational content explaining the probability theory, and visual probability comparison showing the mathematical advantage of switching doors. The project serves both as an entertaining game and an educational tool, making complex probability concepts accessible through hands-on interaction. Built with modern web technologies and featuring smooth animations, hover effects, and polished UI components with gradient backgrounds and glass morphism effects.","images":[{"src":"monthy_hall/home.jpg","alt":"Monty Hall game interface showing three doors with instructions and probability explanation","title":"Main Game Interface"},{"src":"monthy_hall/door.jpg","alt":"Monty Hall game with door selection and probability cards visible","title":"Door Selection State"},{"src":"monthy_hall/open.jpg","alt":"Monty Hall game showing opened door with animated gift reveal","title":"Prize Reveal Animation"}],"technologies":[{"name":"Vue.js 2","icon":"vue.svg"},{"name":"JavaScript ES6+","icon":"js.svg"},{"name":"CSS3","icon":"w3_css-icon.svg"},{"name":"HTML5","icon":"w3_html5-icon.svg"},{"name":"CSS Grid","icon":"grid.svg"},{"name":"CSS Animations","icon":"animation.svg"},{"name":"Responsive Design","icon":"w3_css-icon.svg"}],"links":{"repository":"https://github.com/mopanc/montyhall","website":null}}]}')}}]);